import * as Dialog from '@radix-ui/react-dialog'
import { Loader2, X } from 'lucide-react'
import { useEffect, useState } from 'react'
import { fmtTime } from '@/lib/api'
import { cn } from '@/lib/utils'
import { FlowGraph } from './FlowGraph'
import { ChannelIcon, StepIcon } from './RoutineFlow'
import { MODES, didLines, modeOf, type Mode, type Routine, type Run, type Spec } from './types'

// The routine as its When / Then / Always diagram, full width: the demo's key moment. Opened
// from Today ("Show me how" after a decision, "How it decided" in a review), from a routine's
// "Expand", and for a fresh draft with its test run and "Turn on" (it starts by asking).
// On a phone FlowGraph falls back to the vertical flow.

export function TestResult({ run, spec, title = "Test on today's inbox" }: { run: Run; spec?: Spec | null; title?: string }) {
  const lines = didLines(run, spec)
  return (
    <div>
      <p className="t-small text-ink-3">{title}</p>
      {!run.ok ? (
        <div className="mt-2">
          <p className="t-body text-late">The test failed, so this version cannot be used.</p>
          <pre className="t-small mt-2 max-h-32 overflow-auto whitespace-pre-wrap rounded-xl bg-soft p-3 text-ink-2">{run.error}</pre>
        </div>
      ) : lines.length === 0 ? (
        <p className="t-body mt-2 text-ink-2">Nothing in today's inbox matches. It waits for the next case like this.</p>
      ) : (
        <ul className="mt-2 space-y-1.5">
          {lines.map((l, i) => (
            <li key={i} className={cn('t-body flex items-start gap-2.5', run.dry ? 'text-ink' : 'text-routine')}>
              <span className="mt-[5px] shrink-0">
                {l.kind === 'send' ? <StepIcon step={{ do: 'carry_out' }} size={15} />
                  : l.kind === 'note' ? <StepIcon step={{ do: 'log' }} size={15} />
                  : l.kind === 'tell' ? <ChannelIcon channel={l.channel} size={15} />
                  : <StepIcon step={{ do: l.kind }} size={15} />}
              </span>
              <span className="min-w-0 break-words">{l.text}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

/** "Ask me · Do it and tell me · Do it quietly" as quiet text, the chosen one in ink. */
export function TrustControl({
  value, onChange, disabled, dim,
}: { value: Mode; onChange: (m: Mode) => void; disabled?: boolean; dim?: boolean }) {
  return (
    <div role="radiogroup" aria-label="How it acts" className={cn('t-small flex flex-wrap items-baseline gap-x-1', dim && 'opacity-60')}>
      {MODES.map((m, i) => (
        <span key={m.key} className="inline-flex items-baseline gap-x-1">
          {i > 0 && <span aria-hidden className="text-ink-3">·</span>}
          <button
            type="button"
            role="radio"
            aria-checked={value === m.key}
            disabled={disabled}
            title={m.hint}
            onClick={() => value !== m.key && onChange(m.key)}
            className={cn(
              'cursor-pointer whitespace-nowrap rounded px-0.5 focus-visible:outline-2 focus-visible:outline-accent disabled:cursor-default',
              value === m.key ? 'font-medium text-ink underline decoration-ink-3 decoration-1 underline-offset-[5px]' : 'text-ink-3 hover:text-ink-2',
            )}
          >
            {m.label}
          </button>
        </span>
      ))}
    </div>
  )
}

export interface DiagramDraft {
  onTurnOn: (mode: Mode) => Promise<void>
  onDiscard: () => void
}

export function DiagramSheet({
  open, onOpenChange, routine, run, writing, error, draft,
}: {
  open: boolean
  onOpenChange: (o: boolean) => void
  routine: Routine | null
  run?: Run
  /** The agent is still writing this routine from the decision with this headline. */
  writing?: string | null
  error?: string
  draft?: DiagramDraft
}) {
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        <Dialog.Overlay className="fade fixed inset-0 z-[80] bg-[rgba(24,24,26,.28)]" />
        <Dialog.Content
          aria-describedby={undefined}
          className={cn(
            'sheet-up fixed z-[90] overflow-y-auto bg-ground focus:outline-none',
            'inset-x-0 bottom-0 max-h-[94vh] rounded-t-[22px] px-6 pb-[max(28px,env(safe-area-inset-bottom))] pt-3 shadow-[0_-10px_40px_-16px_rgba(0,0,0,.25)]',
            'md:inset-x-auto md:bottom-auto md:left-1/2 md:top-[4vh] md:max-h-[92vh] md:w-[min(1180px,calc(100vw-64px))] md:-translate-x-1/2 md:rounded-2xl md:px-12 md:pb-10 md:pt-10 md:shadow-[0_20px_60px_-20px_rgba(0,0,0,.3)]',
          )}
        >
          <div className="mx-auto mb-5 h-[5px] w-9 rounded-full bg-hair md:hidden" aria-hidden="true" />
          <Dialog.Close aria-label="Close" className="absolute right-5 top-5 hidden cursor-pointer rounded-md p-2 text-ink-3 hover:text-ink md:block">
            <X size={20} strokeWidth={1.75} />
          </Dialog.Close>
          <Body routine={routine} run={run} writing={writing} error={error} draft={draft} onClose={() => onOpenChange(false)} />
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

function Body({
  routine, run, writing, error, draft, onClose,
}: { routine: Routine | null; run?: Run; writing?: string | null; error?: string; draft?: DiagramDraft; onClose: () => void }) {
  const [mode, setMode] = useState<Mode>('ask')
  const [busy, setBusy] = useState(false)
  const [failed, setFailed] = useState('')
  useEffect(() => { setMode('ask'); setFailed('') }, [routine?.id])

  if (!routine) {
    return (
      <div className="max-w-[640px]">
        <Dialog.Title className="t-small font-normal text-ink-3">{writing ? 'Writing a routine from your decision' : 'Routine'}</Dialog.Title>
        {error ? (
          <p className="t-body mt-4 text-late" role="alert">{error}</p>
        ) : (
          <>
            <p className="t-big mt-3 flex items-center gap-3 text-ink"><Loader2 size={26} className="animate-spin text-ink-3" /> One moment…</p>
            {writing && <p className="t-body mt-5 text-ink-2">From “{writing}”. The agent writes the steps, checks them in the sandbox and tests them on today's inbox before you see them. Up to half a minute.</p>}
          </>
        )}
      </div>
    )
  }

  const spec = routine.spec
  const shown = draft ? mode : modeOf(routine)
  async function turnOn() {
    if (!draft) return
    setBusy(true); setFailed('')
    try { await draft.onTurnOn(mode); onClose() } catch (e) { setFailed(`Could not turn it on: ${(e as Error).message}.`) } finally { setBusy(false) }
  }

  return (
    <>
      <Dialog.Title className="t-small font-normal text-ink-3">{draft ? 'Suggested routine, not on yet' : routine.enabled ? 'Your routine' : 'Your routine, off'}</Dialog.Title>
      <h2 className="t-big mt-2 max-w-[820px] text-ink">{routine.name}</h2>
      {routine.description && <p className="t-body mt-3 max-w-[720px] text-ink-2">{routine.description}</p>}

      <div className="mt-10">
        {spec ? <FlowGraph spec={spec} run={run} wide /> : <p className="t-body text-ink-2">An earlier routine, written as code. Ask the agent for a new one to see it as a diagram.</p>}
      </div>

      <div className="mt-4 grid max-w-[1000px] gap-x-16 gap-y-10 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
        {run && <TestResult run={run} spec={spec} title={run.dry ? "Test run on today's inbox" : `Last run at ${fmtTime(run.at)}`} />}
        <div>
          <p className="t-small text-ink-3">How it acts</p>
          <div className="mt-2">
            {draft ? <TrustControl value={mode} onChange={setMode} disabled={busy} /> : <p className="t-body text-ink">{MODES.find((m) => m.key === shown)?.label}</p>}
          </div>
          <p className="t-small mt-2 text-ink-2">
            {shown === 'ask' ? 'It prepares them; you send with one tap.' : MODES.find((m) => m.key === shown)?.hint + '.'} Anything that costs money still comes to you.
          </p>
        </div>
      </div>

      {draft && (
        <div className="mt-10">
          {failed && <p className="t-small mb-3 text-late" role="alert">{failed}</p>}
          <div className="flex flex-wrap items-center gap-6">
            <button
              onClick={turnOn}
              disabled={busy || (run ? !run.ok : false)}
              autoFocus
              className="t-body inline-flex h-12 cursor-pointer items-center justify-center rounded-xl bg-accent px-7 font-medium text-white shadow-[0_1px_2px_rgba(35,72,208,.25)] hover:bg-[#1d3db5] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent disabled:opacity-60"
            >
              {busy ? 'Turning on…' : mode === 'ask' ? 'Turn on, ask me first' : 'Turn on'}
            </button>
            <button onClick={() => { draft.onDiscard(); onClose() }} className="t-body cursor-pointer text-ink-2 hover:text-ink">Not now</button>
          </div>
        </div>
      )}
    </>
  )
}

/** Load one routine by id and show its diagram (from a proposal review). */
export function RoutineDiagramById({ routineId, onClose }: { routineId: string | null; onClose: () => void }) {
  const [routine, setRoutine] = useState<Routine | null>(null)
  const [error, setError] = useState('')
  useEffect(() => {
    setRoutine(null); setError('')
    if (!routineId) return
    fetch('/api/routines')
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`the server answered ${r.status}`))))
      .then((d: { routines?: Routine[] }) => {
        const r = d.routines?.find((x) => x.id === routineId)
        if (r) setRoutine(r)
        else setError('This routine is gone.')
      })
      .catch((e: Error) => setError(`Could not load it: ${e.message}.`))
  }, [routineId])
  return (
    <DiagramSheet open={!!routineId} onOpenChange={(o) => !o && onClose()} routine={routine} run={routine?.runs?.[0]} error={error} />
  )
}

