            'inset-x-0 bottom-0 max-h-[94vh] rounded-t-[22px] px-6 pb-[max(28px,env(safe-area-inset-bottom))] pt-3 shadow-[0_-10px_40px_-16px_rgba(0,0,0,.25)]',
            'md:inset-x-auto md:bottom-auto md:left-1/2 md:top-[4vh] md:max-h-[92vh] md:w-[min(1040px,calc(100vw-64px))] md:-translate-x-1/2 md:rounded-2xl md:px-12 md:pb-10 md:pt-10 md:shadow-[0_20px_60px_-20px_rgba(0,0,0,.3)]',
          )}
        >
          <div className="mx-auto mb-5 h-[5px] w-9 rounded-full bg-hair md:hidden" aria-hidden="true" />
          <Dialog.Close aria-label="Close" className="absolute right-5 top-5 hidden cursor-pointer rounded-md p-2 text-ink-3 hover:text-ink md:block">
            <X size={20} strokeWidth={1.75} />
          </Dialog.Close>
          <Dialog.Title className="t-small mb-2 font-normal text-ink-3">{label}</Dialog.Title>
          {children}
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  )
}

/** While the agent writes a routine from a decision, or when it could not. */
export function Writing({ from, error }: { from?: string; error?: string }) {
  if (error) return <p className="t-body mt-4 max-w-[640px] text-late" role="alert">{error}</p>
  return (
    <div className="max-w-[640px]">
      <p className="t-big mt-2 flex items-center gap-3 text-ink"><Loader2 size={26} className="animate-spin text-ink-3" /> Writing it…</p>
      <p className="t-body mt-5 text-ink-2">
        {from ? <>From “{from}”. </> : null}The agent writes the steps, checks them in the sandbox and tests them on today's inbox before you see them. Up to half a minute.
      </p>
    </div>
  )
}

/** The drafted routine after "Show me how": writing, then the routine with Turn on / Not now. */
export function DraftDialog({
  open, onOpenChange, from, error, draft, onTurnOn, onDiscard, onReplace, onChanged,
}: {
  open: boolean
  onOpenChange: (o: boolean) => void
  from?: string
  error?: string
  draft: { routine: Routine; preview: Run } | null
  onTurnOn: (mode: Mode) => Promise<void>
  onDiscard: () => void
  onReplace: (r: Routine, preview: Run) => void
  onChanged: () => void
}) {
  return (
    <RoutineDialog open={open} onOpenChange={onOpenChange} label={draft ? 'Handle them the same way' : 'Writing a routine from your decision'}>
      {draft ? (
        <RoutineCard
          key={draft.routine.id}
          big
          routine={draft.routine}
          onChanged={onChanged}
          draft={{
            preview: draft.preview,
            onTurnOn: async (mode) => { await onTurnOn(mode); onOpenChange(false) },
            onDiscard: () => { onDiscard(); onOpenChange(false) },
            onReplace,
          }}
        />
      ) : (
        <Writing from={from} error={error} />
      )}
    </RoutineDialog>
  )
}

/** Load one routine by id and show it (from "How it decided" in a review). */
export function RoutineById({ routineId, onClose, onChanged }: { routineId: string | null; onClose: () => void; onChanged?: () => void }) {
  const [routine, setRoutine] = useState<Routine | null>(null)
  const [error, setError] = useState('')
  const load = (id: string) =>
    fetch('/api/routines')
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`the server answered ${r.status}`))))
      .then((d: { routines?: Routine[] }) => {
        const r = d.routines?.find((x) => x.id === id)
        if (r) setRoutine(r)
        else setError('This routine is gone.')
      })
      .catch((e: Error) => setError(`Could not load it: ${e.message}.`))
  useEffect(() => {
    setRoutine(null); setError('')
    if (routineId) void load(routineId)
  }, [routineId])
  return (
    <RoutineDialog open={!!routineId} onOpenChange={(o) => !o && onClose()} label="How it decided">
      {routine ? (
        <RoutineCard big routine={routine} onChanged={() => { if (routineId) void load(routineId); onChanged?.() }} />
      ) : error ? (
        <p className="t-body mt-2 text-late" role="alert">{error}</p>
      ) : (
        <p className="t-body mt-2 flex items-center gap-2 text-ink-3"><Loader2 size={16} className="animate-spin" /> Loading…</p>
      )}
    </RoutineDialog>
  )
}
